@Service
public class GraphUtil {

    public GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
        GraphPath<V, E> path = new GraphPath<V, E>();
        if (tour.isEmpty()) {
            return path; // Handle empty set gracefully
        }

        V currentVertex = tour.iterator().next(); // Set the starting vertex
        path.addVertex(currentVertex); // Add the starting vertex to the path

        while (true) {
            Set<E> nextEdges = graph.getEdges(currentVertex); // Get the edges from the current vertex
            if (nextEdges.isEmpty()) {
                break; // No more edges, end the path
            }

            E nextEdge = currentEdge.getRandom(); // Select a random edge
            V nextVertex = graph.getOtherVertex(currentVertex, nextEdge); // Get the next vertex

            if (!path.containsVertex(nextVertex)) {
                path.addVertex(nextVertex); // Add the next vertex to the path
                currentVertex = nextVertex; // Move to the next vertex
            } else {
                break; // Loop back if it forms a cycle
            }
        }

        return path; // Return the completed path
    }
}

