public class GraphUtils {
    @SuppressWarnings("unchecked")
    public static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
        // List of all vertices in the graph
        List<V> allVertices = graph.vertexSet().stream().collect(Collectors.toList());

        // Remove the vertices from the set of vertices to check if they form a clique
        List<V> verticesToCheck = allVertices.stream()
                                        .filter(v -> !vertices.contains(v))
                                        .collect(Collectors.toList());

        if (verticesToCheck.isEmpty()) {
            return true;
        }

        // Check if every vertex in verticesToCheck is connected to every vertex in vertices
        for (V vertexToCheck : verticesToCheck) {
            for (V vertex : verticesToCheck) {
                if (!graph.containsEdge(vertexToCheck, vertex)) {
                    return false;
                }
            }
        }

        return true;
    }
}

