public class TimeRangeGenerator {
    protected static final long FETCH_DATA_DURATION = 1000; //假设这是数据获取的持续时间

    protected List<TimeRange> buildTimeRanges(long start, long end) {
        if (start >= end || end >= FETCH_DATA_DURATION + start) {
            throw new IllegalArgumentException("Invalid time range. Start time must be before end time and less than FETCH_DATA_DURATION.");
        }

        List<TimeRange> timeRanges = new ArrayList<>();
        for (long currentStart = start; currentStart < end; currentStart += FETCH_DATA_DURATION) {
            long currentEnd = Math.min(currentStart + FETCH_DATA_DURATION, end);
            timeRanges.add(new TimeRange(currentStart, currentEnd));
        }

        // If there is a remaining segment that is not full, add it
        if (start +Fetch_DATA_DURATION >= end) {
            timeRanges.add(new TimeRange(start + FETCH_DATA_DURATION, end));
        }

        return timeRanges;
    }

