     * Creates a new DataBucket with an empty set.
     */
    public DataBucket() {
        this.bucket = new HashSet<>();
    }

    /**
     * Adds elements to the bucket.
     * @param elements The elements to add.
     */
    public void addElements(String... elements) {
        this.bucket.addAll(elements);
    }

    /**
     * Checks if the bucket is same as another DataBucket.
     * Two DataBucket are considered same if they have the same elements.
     * @param otherBucket The other DataBucket to compare with.
     * @return true if the buckets are same, false otherwise.
     */
    public boolean isCompatible(DataBucket otherBucket) {
        return this.bucket.equals(otherBucket.bucket);
    }

    /**
     * Main method for testing.
     * @param args Command line arguments (not used).
     */
    public static void main(String[] args) {
        DataBucket dataBucket1 = new DataBucket();
        dataBucket1.addElements("a", "b", "c");

        DataBucket dataBucket2 = new DataBucket();
        dataBucket2.addElements("a", "b", "c");
        dataBucket2.addElements("d");

