import org.apache.avro.Schema;

public class CodecUtil {
    public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
        // Step 1: Get the length of the message
        int messageSize = schema.calculateSize(message);

        // Step 2: Write the message to the output stream
        out.write(IntegerEncoder.encodeInt(messageSize));
        schema.validate(message);
        out.write(schema.serialize(message));

        // Step 3: Calculate the total size of the output
        int totalSize = buffer.getPosition() + messageSize + sizeofInt;
        buffer.incrementPosition(messageSize + sizeofInt);

        return totalSize;
    }
}

