import java.nio.charset.StandardCharsets;

public class UTF8SizeCalculator {

    public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
        int byteCount = 0;
        for (int i = index; i < Math.min(index + len, str.length()); i++) {
            int b = str.charAt(i) & 0xFF;
            if (b >= 0xF0) {
                byteCount += 4; // 4-byte sequence
            } else if (b >= 0xE0) {
                byteCount += 3; // 3-byte sequence
            } else if (b >= 0xC0) {
                byteCount += 2; // 2-byte sequence
            } else {
                byteCount++; // 1-byte sequence
            }
        }
        return byteCount;
    }

}

